def map(*, queries: Optional[StrOrPath] = None, tagger_db: Optional[StrOrPath] = None, input: Optional[StrOrPath] = None, ontology_id: Optional[StrOrPath] = None, base_iri: Optional[Sequence[StrOrPath]] = None, preferred_prefix: Optional[StrOrPath] = None, delimiters: Optional[StrOrPath] = None, no_substrings: bool = False, embeddings: Optional[StrOrPath] = None, model: Optional[StrOrPath] = None, base_url: Optional[StrOrPath] = None, api_key: Optional[StrOrPath] = None, min_similarity: Optional[StrOrPath] = None, fuzzy: bool = False, target_ontology: Optional[Sequence[StrOrPath]] = None, limit: Optional[StrOrPath] = None, top_n: Optional[StrOrPath] = None, format: Optional[StrOrPath] = None, binary: Optional[StrOrPath] = None, cwd: Optional[StrOrPath] = None, env: Optional[Mapping[str, str]] = None, capture: bool = True, raise_on_error: bool = True, timeout: Optional[float] = None) -> OwlmakeResult:
    """Map free-text strings to ontology terms (hybrid: tagger lexical + embedding + fuzzy, fused and ranked)

    Flags:
    queries: (--queries) [required] File of query strings, one per line (a trailing tab-separated column, e.g. a property type, is ignored)
    tagger_db: (--tagger-db) Prebuilt tagger DB (raw `.bin` or published `.bin.gz`)
    input: (--input / -i) Ontology to build a transient in-memory tagger from (when no --tagger-db)
    ontology_id: (--ontology-id) Ontology id for the transient build (`--input`)
    base_iri: (--base-iri) Defining base IRI(s) for the transient build. Repeatable
    preferred_prefix: (--preferred-prefix) OBO preferred prefix for the transient build
    delimiters: (--delimiters) Word-boundary delimiter characters for the tagger
    no_substrings: (--no-substrings) Drop matches contained within a longer match (OLS `includeSubstrings=false`)
    embeddings: (--embeddings) Embedding parquet (`om embeddings build`); enables the semantic channel
    model: (--model) Embedding model for the query
    base_url: (--base-url)
    api_key: (--api-key)
    min_similarity: (--min-similarity) Minimum embedding score (`(cos+1)/2`) to keep a semantic hit
    fuzzy: (--fuzzy) Enable the token-Jaccard fuzzy channel (owlmake extension; needs a term source)
    target_ontology: (--target-ontology) Target ontology id(s), priority-ordered; filters and tie-breaks results
    limit: (--limit) Max candidates per query
    top_n: (--top-n) Return the top-N ranked candidates instead of zooma's single-best dedup. Skips the suppression cascade (keepBestEmbedding / suppressWeak / keepBestPerTargetOntology) so a query can yield several ranked candidates per ontology — useful when a downstream stage selects among them. Caps output at N (overriding --limit). Default: off (zooma parity)
    format: (--format / -f) Output format: table (default) or json
    """
    return _rt.run_command('map', {
        "queries": queries,
        "tagger_db": tagger_db,
        "input": input,
        "ontology_id": ontology_id,
        "base_iri": base_iri,
        "preferred_prefix": preferred_prefix,
        "delimiters": delimiters,
        "no_substrings": no_substrings,
        "embeddings": embeddings,
        "model": model,
        "base_url": base_url,
        "api_key": api_key,
        "min_similarity": min_similarity,
        "fuzzy": fuzzy,
        "target_ontology": target_ontology,
        "limit": limit,
        "top_n": top_n,
        "format": format,
    }, binary=binary, cwd=cwd, env=env, capture=capture, raise_on_error=raise_on_error, timeout=timeout)


