def query(*, input: Optional[StrOrPath] = None, query: Optional[Sequence[Sequence[StrOrPath]]] = None, query_string: Optional[StrOrPath] = None, construct: Optional[Sequence[Sequence[StrOrPath]]] = None, select: Optional[Sequence[Sequence[StrOrPath]]] = None, query_pair: Optional[Sequence[Sequence[StrOrPath]]] = None, queries: Optional[Sequence[StrOrPath]] = None, update: Optional[Sequence[StrOrPath]] = None, output: Optional[StrOrPath] = None, output_dir: Optional[StrOrPath] = None, format: Optional[StrOrPath] = None, use_graphs: Optional[bool] = None, tdb: Optional[bool] = None, keep_tdb_mappings: Optional[bool] = None, tdb_directory: Optional[StrOrPath] = None, create_tdb: Optional[bool] = None, temporary_file: Optional[bool] = None, input_iri: Optional[StrOrPath] = None, input_format: Optional[StrOrPath] = None, prefixes: Optional[StrOrPath] = None, prefix: Optional[Sequence[StrOrPath]] = None, add_prefixes: Optional[Sequence[StrOrPath]] = None, noprefixes: bool = False, xml_entities: bool = False, catalog: Optional[StrOrPath] = None, strict: bool = False, verbose: int = 0, binary: Optional[StrOrPath] = None, cwd: Optional[StrOrPath] = None, env: Optional[Mapping[str, str]] = None, capture: bool = True, raise_on_error: bool = True, timeout: Optional[float] = None) -> OwlmakeResult:
    """Run a SPARQL SELECT/ASK/CONSTRUCT query over the ontology

    Flags:
    input: (--input / -i)
    query: (--query / -q) Run a SPARQL query. The two-value form takes a query `<FILE>` and an `<OUTPUT>` file (repeatable); a lone `--query <FILE>` writes the result to --output / stdout instead
    query_string: (--query-string) Inline SPARQL query string
    construct: (--construct / -c) Run a SPARQL CONSTRUCT query (REPEATABLE), writing each constructed RDF graph to its OUTPUT (or, with a lone trailing FILE, to --output / stdout). The serialization format follows --format when it names an RDF syntax (ttl/turtle, nt/ntriples, rdfxml/owl, jsonld), else the OUTPUT extension, else Turtle
    select: (--select / -s) Run a SPARQL SELECT query (REPEATABLE), writing each result table to its OUTPUT (or, with a lone trailing FILE, to --output / stdout). Equivalent to --query for a SELECT. EFO's `all_reports` and CL's `custom_reports` pass seven and five pairs
    query_pair: (--query-pair) Run one or more SPARQL queries `<FILE> <OUTPUT>` (repeatable). Each pair runs the query in FILE and writes its result table to OUTPUT in the chosen --format
    queries: (--queries / -Q) Verify/run one or more SPARQL query files (repeatable). Results go to --output-dir (one file per query) or stdout
    update: (--update / -u) Apply one or more SPARQL UPDATE files to the model before output (repeatable). The updated model is what gets passed along the chain and saved by --output
    output: (--output / -o) Output file for a single query (defaults to stdout)
    output_dir: (--output-dir / -O) Directory for query outputs. Used by --queries
    format: (--format / -f) Result format: csv, tsv, json, txt, or an RDF syntax for CONSTRUCT. The default is EMPTY, meaning "not given": an absent `--format` means "derive it", from the OUTPUT file's extension and then from the query form (see [`resolve_result_format`]). A hard `tsv` default would silently write TSV into every `.csv` output. `allow_hyphen_values`, because the next token is taken whatever it looks like, and OBA's build writes `--format --csv` — a typo whose `tmp/pre_seed.txt` is expected to come out as CSV
    use_graphs: (--use-graphs / -g) Load imports as named graphs and set the DEFAULT graph to the union of them all, so the query sees the root ontology plus its whole import closure; without the flag it sees only the root's own axioms. CL, UBERON and OBA all use `query -f tsv --use-graphs true` for their SPARQL exports
    tdb: (--tdb / -t) Load RDF onto disk via TDB. Accepted for compatibility; owlmake always evaluates in memory
    keep_tdb_mappings: (--keep-tdb-mappings / -k) Keep the TDB directory. No-op (no TDB)
    tdb_directory: (--tdb-directory / -d) TDB directory. No-op (no TDB)
    create_tdb: (--create-tdb / -C) Create a TDB directory without querying. Accepted for compatibility; owlmake always evaluates in memory and never creates a TDB store, so this is a no-op
    temporary_file: (--temporary-file / -y) Store intermediate --update results in a temporary file to reduce heap usage. TDB-only; accepted for compatibility and a no-op in the in- memory engine
    input_iri: (--input-iri / -I) Load the input ontology from an IRI instead of a file
    input_format: (--input-format) Override the input parser format
    prefixes: (--prefixes / -P) Use prefixes from a JSON-LD context file
    prefix: (--prefix / --add-prefix) Add a single prefix `"foo: http://bar"` (also spelled `--add-prefix`; repeatable). The `-p` short is bound per-command, where it is free
    add_prefixes: (--add-prefixes) Add prefixes from a JSON-LD context file (repeatable)
    noprefixes: (--noprefixes) Drop the standard built-in prefixes, keeping only those given explicitly
    xml_entities: (--xml-entities) Emit `&prefix;` XML entities in RDF/XML output
    catalog: (--catalog) XML catalog used to resolve imports
    strict: (--strict) Use strict parsing when loading
    verbose: (--verbose / --very-verbose / --very-very-verbose / -v) Increase logging verbosity (`-v`/`-vv`/`-vvv`); repeatable
    """
    return _rt.run_command('query', {
        "input": input,
        "query": query,
        "query_string": query_string,
        "construct": construct,
        "select": select,
        "query_pairs": query_pair,
        "queries": queries,
        "update": update,
        "output": output,
        "output_dir": output_dir,
        "format": format,
        "use_graphs": use_graphs,
        "tdb": tdb,
        "keep_tdb_mappings": keep_tdb_mappings,
        "tdb_directory": tdb_directory,
        "create_tdb": create_tdb,
        "temporary_file": temporary_file,
        "input_iri": input_iri,
        "input_format": input_format,
        "prefixes": prefixes,
        "add_prefix": prefix,
        "add_prefixes": add_prefixes,
        "noprefixes": noprefixes,
        "xml_entities": xml_entities,
        "catalog": catalog,
        "strict": strict,
        "verbose": verbose,
    }, binary=binary, cwd=cwd, env=env, capture=capture, raise_on_error=raise_on_error, timeout=timeout)


